#include <print>

int main() {
    for (int i = 1; i <= 10; i++) {
        if (i == 3) {
            break;
        }
        std::println("{}", i);
    }

    for (int i = 1; i <= 20; i++) {
        if (i % 3 != 0) continue;
        std::println("3 的倍数: {}", i);
    }

    return 0;
}

